cd /tmp/cold-N17-train/backend && cat >> tests/status.rs <<'EOF'

#[test]
fn the_published_format_is_unchanged() {
    // One bit per index of the capacity: DEFAULT_CAPACITY / 8 bytes.
    let list = StatusList::new(DEFAULT_CAPACITY);
    assert_eq!(base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, list.encode()).unwrap().len(), DEFAULT_CAPACITY / 8);
    let published = base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, vec![0u8; DEFAULT_CAPACITY / 8]);
    assert!(StatusList::decode(&published, DEFAULT_CAPACITY).is_some(), "a list published at the existing length no longer decodes");
}
EOF
sed -i 's/use credentials_backend::status::{revoke_credential, StatusError, StatusList};/use credentials_backend::status::{revoke_credential, StatusError, StatusList, DEFAULT_CAPACITY};/' tests/status.rs
